import React from 'react';
import './Team.css';

const Team = () => {
  const teamMembers = [
    {
      name: 'Shaik Md Farooq Ali',
      role: 'Founder & Managing Director',
      expertise: 'Embedded Systems & IoT Integration',
      description: 'An accomplished technologist leading OLT’s product strategy, embedded hardware architecture, and industrial IoT solutions.',
      icon: 'fa-user-tie'
    },
    {
      name: 'Salar Khan Patan',
      role: 'CEO & Co-founder',
      expertise: 'System Optimization & Operations',
      description: 'Electrical Engineer focusing on hands-on system engineering, operational execution, and industrial partner integration.',
      icon: 'fa-briefcase'
    },
    {
      name: 'Pandipati Sai Karthik',
      role: 'Co-founder & CTO',
      expertise: 'Hardware & Software Architecture',
      description: 'Bridging the gap between embedded hardware controllers, firmware design, and scalable cloud application backends.',
      icon: 'fa-code-branch'
    },
    {
      name: 'Pavan Kumar',
      role: 'Computer Vision & AI Lead',
      expertise: 'AI Models & Sensor Telemetry',
      description: 'Specializing in edge computer vision algorithms, real-time object detection models, and intelligent telemetry processing.',
      icon: 'fa-brain'
    },
    {
      name: 'Dr. K Narasimha Raju',
      role: 'Director & Academic Advisor',
      expertise: 'Power Systems & Automation',
      description: 'Professor at KLEF Deemed To Be University providing strategic guidance on power electronics and control systems engineering.',
      icon: 'fa-graduation-cap'
    },
    {
      name: 'Dr. Kalyan D',
      role: 'Director & R&D Advisor',
      expertise: 'Industrial Technology & Research',
      description: 'Professor at KLEF Deemed To Be University advising OLT on advanced research methodology and industrial tech deployment.',
      icon: 'fa-microchip'
    },
    {
      name: 'Srikanth Annamareddy',
      role: 'Operations & Global Strategy Advisor',
      expertise: 'Supply Chain & International Growth',
      description: 'Operations Supervisor at Costco Wholesale Coventry, UK, advising OLT on global operational strategy and scaling.',
      icon: 'fa-globe-europe'
    },
    {
      name: 'Madhusudhan',
      role: 'Software & Data Architecture Advisor',
      expertise: 'Data Engineering & Cloud Systems',
      description: 'Senior Data Engineer at ASX Sydney, Australia, guiding OLT’s enterprise data architecture and cloud analytics pipeline.',
      icon: 'fa-database'
    }
  ];

  return (
    <section id="team" className="section team-section">
      <div className="container">
        <div className="section-header">
          <span className="badge-tag">LEADERSHIP & ADVISORS</span>
          <h2 className="section-title">The Engineering & Strategic Mindset Behind OLT</h2>
          <p className="section-subtitle">
            A multidisciplinary team of founders, researchers, software engineers, and global industry advisors driving deep-tech innovation.
          </p>
        </div>

        <div className="team-grid">
          {teamMembers.map((member, index) => (
            <div key={index} className="team-card-item">
              <div className="team-card-top">
                <div className="team-avatar-box">
                  <i className={`fas ${member.icon}`}></i>
                </div>
                <span className="team-expertise-tag">{member.expertise}</span>
              </div>

              <div className="team-card-body">
                <h3 className="team-member-name">{member.name}</h3>
                <span className="team-member-role">{member.role}</span>
                <p className="team-member-desc">{member.description}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Team;
